import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Formatter as a Production Pipeline (FormatEngine stage contracts) — design detail","description":"","frontmatter":{"title":"Formatter as a Production Pipeline (`FormatEngine` stage contracts) — design detail","type":"design","date":"2026-09-08T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","refs":["ADR-0095"]},"headers":[],"relativePath":"handl/project/design/0095-formatter-as-production-pipeline.md","filePath":"vendored/handl/project/design/0095-formatter-as-production-pipeline.md"}'),a={name:`handl/project/design/0095-formatter-as-production-pipeline.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0095-formatter-as-a-production-pipeline-formatengine-stage-contracts-—-design-detail" tabindex="-1">ADR-0095: Formatter as a Production Pipeline (<code>FormatEngine</code> stage contracts) — design detail <a class="header-anchor" href="#adr-0095-formatter-as-a-production-pipeline-formatengine-stage-contracts-—-design-detail" aria-label="Permalink to “ADR-0095: Formatter as a Production Pipeline (FormatEngine stage contracts) — design detail”">​</a></h1><p>Moved verbatim from ADR-0095 (ADR-0161 size budget). The ADR carries the rules; this page carries the mechanism, tables and rationale.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The test-runner rewrite in <a href="./0089-bootstrap-test-runner.html">ADR-0089</a> named the anti-pattern it was avoiding: <strong>building a toy and bolting production features on later</strong> is exactly what ADR-0085 rule 2 exists to prevent, and a handl port is only low-risk if the Rust original is already structured the way the handl version will be. The formatter is today in the shape ADR-0089&#39;s Context criticized:</p><ol><li><strong>The canonical layout is a hardcoded monolith.</strong> In <code>plugin-ext-fmt/src/lib.rs</code>, <code>format_source</code> is one function chain — <code>parse → lex → format_tokens → post_process</code> — over 500+ lines of inline rules: the <code>TokenCat</code> enum, <code>needs_space</code>, <code>indent_str</code>, <code>post_process</code>, and <code>decl_type</code>. Every canonical-style rule (spacing, chain-breaking, blank-line policy, trailing-NL) is baked into that walk. There are no stage boundaries and no seams. A style change is surgery on the chain.</li><li><strong>The generic formatter capability is disconnected.</strong> <code>crates/platform/ src/format.rs</code> ships <code>BasicFormatter</code> / <code>FormatBehavior</code> / <code>FormatRequest</code> — ADR-0014&#39;s &quot;generic core, pluggable rules&quot; — but they key rules by <code>AstNode.kind</code>, operate on a single node payload, and are exercised only by echo-style unit tests. The real canonical formatter never goes through them. ADR-0014&#39;s generic purpose was never connected to ADR-0086&#39;s concrete implementation.</li><li><strong>Two engines, not a pipeline.</strong> <code>plugin-engine-fmt</code> already has a data-driven AST→source emitter (<code>FormatEngine</code> + a <code>NodeEmitter</code> trait: <code>PlainEmitter</code> / <code>PreserveEmitter</code>, per ADR-0044). The token-stream layout in <code>plugin-ext-fmt</code> reimplements the leaf/spacing decisions separately. They are alternatives, not stages of one pipeline.</li><li><strong>Future work is a catch-all, not a contract.</strong> ADR-0086 deferred config, plugin-contributed rules, and comment reflow to RFC-0002. That deferral is fine — but without stage/rule boundaries in Rust now, RFC-0002 stays a rewrite instead of becoming the port ADR-0085 rule 6 wants.</li></ol><p>What the formatter already has that the runner did not: a real generic parse/lex substrate (reused, not owned), a data-driven AST emitter with a <code>NodeEmitter</code> seam, and a golden corpus + idempotence test suite. So this is primarily a <strong>land-the-boundaries</strong> change, not a rebuild.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Refactor the formatter into a <strong>production pipeline with stable contracts between stages</strong> — <code>parse → layout → render → post-process</code> — land the boundaries now, and ship the existing implementations behind them. Future features (config, plugin rules, a handl engine, comment reflow, incremental LSP formatting) become new implementations/compositions, not architectural surgery.</p><h3 id="crate-boundary" tabindex="-1">Crate boundary <a class="header-anchor" href="#crate-boundary" aria-label="Permalink to “Crate boundary”">​</a></h3><table tabindex="0"><thead><tr><th>Crate</th><th>Role</th><th>Fate</th></tr></thead><tbody><tr><td><code>plugin-engine-fmt</code> (<strong>core</strong>)</td><td>Format <strong>engine</strong>: the staged pipeline plus the <code>NodeEmitter</code> and <code>FormattingRule</code> seams. Language-generic (ADR-0044/ADR-0041).</td><td>Improved in place; hosts the pipeline and traits.</td></tr><tr><td><code>plugin-ext-fmt</code> (<strong>surface</strong>)</td><td>Canonical v0.1 <strong>surface</strong>: assemble the canonical kit, select the canonical rule set, expose <code>format_source</code> / <code>check_source</code> / <code>format_ast</code> as thin wrappers + CLI contract + golden/idempotence tests.</td><td>Slimmed to a thin wrapper over the engine pipeline.</td></tr><tr><td><code>crates/platform/format.rs</code></td><td>The generic <code>Format</code> capability (<code>BasicFormatter</code> / <code>FormatBehavior</code>).</td><td><strong>Decision point below.</strong></td></tr></tbody></table><h3 id="pipeline-and-stage-contracts" tabindex="-1">Pipeline and stage contracts <a class="header-anchor" href="#pipeline-and-stage-contracts" aria-label="Permalink to “Pipeline and stage contracts”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Source text</span></span>
<span class="line"><span>   │  parse                          (reuse lex + Pratt; data-driven, ADR-0044)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[tokens, AST]                        ── stage 1 · parse</span></span>
<span class="line"><span>   │  layout</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>LayoutStream (breaks / indents / spacing, per-rule decisions)</span></span>
<span class="line"><span>                                     ── stage 2 · layout</span></span>
<span class="line"><span>   │  render</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>rendered text                        ── stage 3 · render   (Plain | Preserve, via NodeEmitter)</span></span>
<span class="line"><span>   │  post-process</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>canonical source                     ── stage 4 · post-process (blank-lines, trailing NL/WS)</span></span></code></pre></div><p>Each stage has a typed input/output contract. The initial implementation of each stage is exactly the logic that exists today, moved behind the boundary:</p><ul><li><strong>parse</strong> — reuse <code>plugin-engine-lex-*</code> and <code>plugin-engine-parse-pratt</code> (already generic; not reimplemented).</li><li><strong>layout</strong> — <code>needs_space</code> / indentation / chain-breaking move from the monolith into composable rules.</li><li><strong>render</strong> — already exists as <code>FormatEngine</code> + <code>PlainEmitter</code> / <code>PreserveEmitter</code> in <code>plugin-engine-fmt</code>.</li><li><strong>post-process</strong> — <code>post_process</code> / <code>decl_type</code> (blank-line and trailing policy) move behind the boundary.</li></ul><h3 id="rule-seam-formattingrule-replaceable-composable" tabindex="-1">Rule seam: <code>FormattingRule</code> (replaceable, composable) <a class="header-anchor" href="#rule-seam-formattingrule-replaceable-composable" aria-label="Permalink to “Rule seam: FormattingRule (replaceable, composable)”">​</a></h3><p>Introduce <code>pub trait FormattingRule</code> in <code>plugin-engine-fmt</code>. Each canonical-style rule (indentation, chain-breaking, blank-line policy, spacing) is a separate implementation behind the trait, selected/composed by the surface rather than hardcoded inside one walk — the formatter analog of the test runner&#39;s <code>TestProvider</code> seam (ADR-0089 §&quot;Providers (extensible from day one)&quot;). Disabling or reordering a rule is composition, not surgery; a new style for another handl dialect is a new rule set, not a core change.</p><h3 id="config-seam" tabindex="-1">Config seam <a class="header-anchor" href="#config-seam" aria-label="Permalink to “Config seam”">​</a></h3><p><code>FormatOptions</code> (already a <code>{ indent_size }</code> record) becomes the config record RFC-0002 specifies (<code>{ indent, width, ... }</code>), threaded as pipeline <strong>input</strong> — never read from a file by the engine. A later <code>hnl</code> config layer supplies overrides without changing the engine.</p><h3 id="engine-seam-nodeemitter-stays-the-swap-point" tabindex="-1">Engine seam: <code>NodeEmitter</code> stays the swap point <a class="header-anchor" href="#engine-seam-nodeemitter-stays-the-swap-point" aria-label="Permalink to “Engine seam: NodeEmitter stays the swap point”">​</a></h3><p>The existing <code>NodeEmitter</code> trait (<code>PlainEmitter</code> / <code>PreserveEmitter</code>) remains the engine boundary. The LSP incremental path (RFC-0002) and the CLI normalizing path share one contract; a future handl / compiled engine is a new <code>NodeEmitter</code> implementation, keeping RFC-0002 a port.</p><h3 id="generic-capability-connect-or-retire-platform-format-rs" tabindex="-1">Generic capability: connect or retire <code>platform/format.rs</code> <a class="header-anchor" href="#generic-capability-connect-or-retire-platform-format-rs" aria-label="Permalink to “Generic capability: connect or retire platform/format.rs”">​</a></h3><p><code>BasicFormatter</code> / <code>FormatBehavior</code> must be one of:</p><ol><li><strong>Wired</strong> to the real engine — <code>BasicFormatter</code> dispatches to the <code>FormatEngine</code> pipeline so ADR-0014&#39;s &quot;generic core, pluggable rules&quot; is real and the plugin-registry path formats actual <code>Ast</code> / <code>Language</code> input; or</li><li><strong>Retired</strong> — documented explicitly that <code>FormatEngine</code> / <code>plugin-ext-fmt</code>&#39;s direct API is the canonical path and the <code>Format</code> capability is deprecated for host use.</li></ol><p>Leaving it disconnected (today&#39;s state) is rejected: it preserves ADR-0014&#39;s facade while guaranteeing drift between the generic and canonical paths.</p><h3 id="language-as-data-style" tabindex="-1">Language-as-data style <a class="header-anchor" href="#language-as-data-style" aria-label="Permalink to “Language-as-data style”">​</a></h3><p>Continue the discipline <code>classify_token</code> already applies (<code>TokenKindDef</code><code>category</code> / <code>label</code>, ADR-0044): spacing and line-break decisions consult <code>Language</code> data rather than hardcoded spellings, so other handl languages get a formatter for free (ADR-0041 &quot;one formatter formats any language you have a value for&quot;).</p><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to “Performance”">​</a></h3><p>Three levers fall out of the stage boundaries, mirroring the runner&#39;s scheduler-based parallelism:</p><ol><li><strong>Parallel <code>--write</code> / <code>--check</code></strong> across many files via <code>plugin-lib-scheduler::BoundedScheduler</code> (reused, as in ADR-0089).</li><li><strong>Stage-boundary caching</strong> — a content-hash key on the parse stage (reusing <code>plugin-exec-cache</code>&#39;s <code>CacheControl</code> idea); only re-layout / re-render changed files.</li><li><strong>Incremental per-document formatting</strong> for the LSP, enabled by the existing <code>PreserveEmitter</code> stage.</li></ol><p>Determinism: parallelism / caching change timing, never output ordering — the ADR-0089 guarantee, applied to formatting.</p><h3 id="public-api-preserved" tabindex="-1">Public API (preserved) <a class="header-anchor" href="#public-api-preserved" aria-label="Permalink to “Public API (preserved)”">​</a></h3><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">pub</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> format_source</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">src</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;">str</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Result</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">String</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> FormatError</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;;</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">pub</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> check_source</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">src</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;">str</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Result</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;">bool</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> FormatError</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;;</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">pub</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> format_ast</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">lang</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Language</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> ast</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Ast</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> root</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> AstRef</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Result</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">String</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> LangError</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;;</span></span></code></pre></div><p>The existing names stay as thin wrappers over the pipeline for callers. <code>FormatError</code> and diagnostics integration (ADR-0091 <code>plugin-ext-diag</code>) are unchanged.</p><h3 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to “Testing”">​</a></h3><p>100% coverage (ADR-0085 rule 4). Keep the golden corpus (<code>plugin-ext-fmt/tests/golden/</code>) and the idempotence property test. Add per-stage contract unit tests and property tests asserting idempotence and determinism as stage laws (<code>fmt(fmt(src)) == fmt(src)</code>; parallel output == serial output).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>The formatter is production-architected, not a throwaway.</strong> RFC-0002 becomes a port of already-generic, well-bounded Rust code — the lowest-risk kind of port per ADR-0085 rule 6.</li><li><strong>Style is composable, not monolithic.</strong> Changing one style rule is editing one rule implementation + bumping goldens, not surgery on a 500-line walk.</li><li><strong>RFC-0002&#39;s deferrals become seams.</strong> Config, plugin rules, comment reflow, incremental LSP formatting each map to a stage or rule contract.</li><li><strong>The generic capability is either real or honestly retired</strong> — no more facade drift between <code>platform/format.rs</code> and the canonical path.</li><li><strong>Performance and determinism are guaranteed</strong>, not incidental.</li><li><strong>Generic infrastructure is reused, not reinvented</strong> (scheduler, cache, lex/parse engines, diagnostics) — the engine owns only formatting glue.</li><li><strong>Other handl languages gain a formatter</strong> as the style follows <code>Language</code> data.</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><ol><li>Extract <code>needs_space</code> / indentation / chain-breaking into <code>FormattingRule</code> implementations in <code>plugin-engine-fmt</code>; keep the current behavior byte-identical on the golden corpus.</li><li>Move <code>post_process</code> / <code>decl_type</code> behind the post-process stage contract.</li><li>Decide and execute the <code>platform/format.rs</code> option (connect or retire).</li><li>Keep 100% coverage and the golden + idempotence suites green through each step.</li><li>No change to ADR-0086&#39;s canonical style or the <code>hnl fmt</code> CLI contract.</li></ol>`,39)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};